def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    prev_bids = []
    dangerous_prev = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if float(bid) >= 70:
                    dangerous_prev.append(float(bid))

    if not alive_opps:
        return float(min(budget, 18.0 if hp > 4 else 40.0))

    tight_supply = supply <= 17.0
    medium_supply = supply <= 20.0
    critical = hp <= 3 or no_water_days >= 2
    pressured = hp <= 5 or no_water_days >= 1

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    rich_alive = 0
    desperate_alive = 0
    for opp in alive_opps:
        if opp.get('budget', 0) >= 120:
            rich_alive += 1
        if opp.get('hp', 10) <= 4 or opp.get('no_water_days', 0) >= 1:
            desperate_alive += 1

    if critical:
        if tight_supply:
            target = max(78.0, highest_prev + 6.0)
        else:
            target = max(62.0, avg_prev + 4.0)
        if budget < target:
            return float(budget)
        return float(min(budget, target))

    if pressured:
        if tight_supply:
            target = max(52.0, min(88.0, highest_prev + 2.5))
        elif medium_supply:
            target = max(40.0, min(72.0, avg_prev + 3.0))
        else:
            target = 28.0
        return float(min(budget, target))

    if tight_supply:
        if highest_prev >= 120.0:
            target = 16.0
        elif highest_prev >= 85.0:
            target = 24.0
        else:
            target = max(30.0, highest_prev + 1.5)
    elif medium_supply:
        if rich_alive >= 2 and highest_prev >= 100.0:
            target = 18.0
        else:
            target = 22.0 if day < 7 else 26.0
    else:
        target = 14.0 if day < 8 else 18.0

    if budget < DAILY_SALARY * 0.6 and hp > 5:
        target = min(target, 20.0)

    return float(max(0.0, min(budget, target)))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 140
    WATER_REQ = 8
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        max_prev = max(yesterday_bids)
        if my_status['hp'] < 4:
            return min(my_status['budget'], max_prev + 10.0)
        return min(my_status['budget'], max(70.0, max_prev + 2.0))

    if my_status['hp'] < 3:
        return min(my_status['budget'], DAILY_SALARY * 0.8)
    return min(my_status['budget'], DAILY_SALARY * 0.5)
